parameters.jsCode:
// 挑今天要拿去搜的電話。安全閥（2026-10-25 建，見 reference.md「疑似同業 Google 搜尋」）：
//   ・查不到 SerpApi 剩餘額度（key 失效、服務掛了）→ 一筆都不搜，交給「額度檢查」推告警
//   ・每班最多 MAX_PER_RUN 筆，且一定留 RESERVE 次給人手動排查
//   ・同一支電話只搜一次（重複搶到的同一人不重花額度）
// ⚠️ Notion 篩選偶爾回索引沒更新的舊值（2026-09-05 事故），payload 這裡一定再驗一次
const MAX_PER_RUN = 10, RESERVE = 10;
const acct = $('查 SerpApi 剩餘額度').first().json;
const left = Number(acct.total_searches_left ?? acct.plan_searches_left);
if (!Number.isFinite(left)) return [];
const budget = Math.max(0, Math.min(MAX_PER_RUN, left - RESERVE));
const seen = new Set(), out = [];
for (const p of ($input.first().json.results || [])) {
  const pr = p.properties || {};
  if (pr['已搜尋']?.checkbox || pr['同業']?.checkbox) continue;
  const phone = String(pr['電話']?.phone_number || '').replace(/\D/g, '');
  if (!/^0\d{8,9}$/.test(phone) || seen.has(phone)) continue;  // 只收台灣手機/市話格式
  seen.add(phone);
  out.push({ json: { pageId: p.id, phone } });
}
return out.slice(0, budget);

// 額度／名單檢查：正常就回空陣列（不推）；有狀況才組一則 Telegram
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); // Telegram HTML 轉義，見 incidents.md 2026-09-23
const MAX_PER_RUN = 10, RESERVE = 10;  // 跟「挑要搜的電話」保持一致
const acct = $('查 SerpApi 剩餘額度').first().json;
const left = Number(acct.total_searches_left ?? acct.plan_searches_left);
const pending = ($input.first().json.results || []).filter(p => {
  const pr = p.properties || {};
  return !pr['已搜尋']?.checkbox && !pr['同業']?.checkbox && pr['電話']?.phone_number;
}).length;
let text = '';
if (!Number.isFinite(left)) {
  text = '⚠️ 疑似同業 Google 搜尋：查不到 SerpApi 剩餘額度（key 失效或服務異常），今天一筆都沒搜。\n'
       + '原因：' + String(acct.error?.message || acct.error || '未知').slice(0, 150);
} else if (left - RESERVE < Math.min(pending, MAX_PER_RUN)) {
  text = `⚠️ 疑似同業 Google 搜尋：SerpApi 本月剩 ${left} 次（保留 ${RESERVE} 次），待搜 ${pending} 筆，`
       + '今天搜不完，額度下個月才會重置。';
}
return text ? [{ json: { text, _tg: esc(text) } }] : [];

// 把每支電話的 Google 結果，篩出「看起來跟房地產有關」的當候選，寫進 Notion 給 Cowork 確認
// 這裡只負責挑候選，絕不勾「同業」「疑似同業」——要不要勾由 Cowork 確認後決定
const KW = ['仲介','房仲','不動產','代書','地政士','地產','房屋','房產','售屋','賣屋','買屋','購屋','租屋',
            '出租','出售','招租','委售','開價','建案','預售','透天','華廈','店面','土地','經紀人','營業員'];
const SITES = ['591.com.tw','rakuya.com.tw','sinyi.com.tw','yungching.com.tw','hbhousing.com.tw',
               'etwarm.com.tw','twhg.com.tw','cthouse.com.tw','century21.com.tw','housefun.com.tw','leju.com.tw'];
const src = $('挑要搜的電話').all();
return $input.all().map((it, i) => {
  const { pageId, phone } = src[i].json;
  const j = it.json;
  if (j.error || !j.search_metadata || j.search_metadata.status !== 'Success') {
    return { json: { pageId, phone, ok: false, why: String(j.error?.message || j.error || j.search_metadata?.status || '無回應').slice(0, 120) } };
  }
  const lines = [];
  for (const r of (j.organic_results || [])) {
    const blob = [r.title, r.snippet, ...(r.snippet_highlighted_words || [])].join(' ');
    const link = String(r.link || '');
    if (!KW.some(k => blob.includes(k)) && !SITES.some(s => link.includes(s))) continue;
    const hit = blob.replace(/\D/g, '').includes(phone) ? '☎摘要有電話' : '☎摘要沒電話';
    lines.push(`${hit}｜${link}｜${String(r.title || '').slice(0, 50)}｜${String(r.snippet || '').slice(0, 90)}`);
    if (lines.length >= 5) break;
  }
  return { json: { pageId, phone, ok: true, text: lines.join('\n').slice(0, 1900) } };
});

