// 搜尋失敗的筆數彙整：失敗的不標「已搜尋」，明天會自動重搜（3 天內）
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); // Telegram HTML 轉義，見 incidents.md 2026-09-23
const bad = $input.all().map(x => x.json);
if (!bad.length) return [];
const text = `⚠️ 疑似同業 Google 搜尋：${bad.length} 筆搜尋失敗（明天自動重搜）\n`
           + bad.slice(0, 5).map(b => '・' + b.why).join('\n');
return [{ json: { text, _tg: esc(text) } }];
